        int n = sc.nextInt();
        Dog d = new Dog("大黄");
        Fish f = new Fish("泡泡");
        Animal a = new Animal("大肥鱼");
        for (int i = 0; i < n; i++) {
            d.speak();
        }
        f.speak();
        a.speak();
    }
}

